import re, collections
t=open('KRATNOST-vladelca.md',encoding='utf-8').read()
# группы: ### N. название — M вхождений, затем строки "- **заголовок** — `адрес`"
gr={}
cur=None
names={}
for line in t.splitlines():
    m=re.match(r'^### (\d+)\. (.+?) — (\d+) вхожден', line)
    if m:
        cur=int(m.group(1)); names[cur]=m.group(2); continue
    m=re.match(r'^- \*\*(.+?)\*\* — `(.+?)`', line)
    if m and cur:
        gr[(m.group(1), m.group(2))]=cur
print("пар (заголовок,адрес) в KRATNOST:", len(gr))

sk={}
for l in open('skelet-vladelca.tsv',encoding='utf-8'):
    if l.startswith('#'): continue
    f=l.rstrip('\n').split('\t'); sk[f[0]]=f
vd={}
for l in open('verdikt-vladelca.tsv',encoding='utf-8'):
    if l.startswith('#') or not l.strip(): continue
    f=l.rstrip('\n').split('\t'); vd[f[0]]=f
mine=sorted(i for i in sk if 'V1036'<=i<='V1379')
mapped={}; miss=[]
for i in mine:
    k=(sk[i][2], sk[i][3])
    if k in gr: mapped[i]=gr[k]
    else: miss.append(i)
print(f"сопоставлено машинно: {len(mapped)} из {len(mine)}; не сопоставилось: {len(miss)}")
if miss: print("  не сопоставились:", miss[:10])

# доминантный ярус группы по ВСЕМУ корпусу
allmap=collections.defaultdict(list)
for i in sk:
    k=(sk[i][2], sk[i][3])
    if k in gr: allmap[gr[k]].append(i)
dom={}
for g,ids in allmap.items():
    c=collections.Counter(vd[i][1] for i in ids if i in vd)
    dom[g]=c.most_common(1)[0][0] if c else '—'
otl=[i for i in mapped if vd[i][1]!=dom[mapped[i]]]
print(f"мой ярус ОТЛИЧАЕТСЯ от доминантного яруса своей группы: {len(otl)} из {len(mapped)} ({100*len(otl)/len(mapped):.0f} %)")
open('/tmp/h2d/gruppy.txt','w',encoding='utf-8').write('\n'.join(
  f"{i}\tгр.{mapped[i]} {names[mapped[i]]}\tмой={vd[i][1]}\tдом={dom[mapped[i]]}\t{sk[i][2]}" for i in sorted(mapped)))
# разброс внутри групп, где у меня >=8 записей
cnt=collections.Counter(mapped.values())
print("\nгруппы, где у меня >= 8 записей — разброс значений ярус·материя:")
for g,n in cnt.most_common():
    if n<8: continue
    vals=collections.Counter(vd[i][1]+'/'+vd[i][2] for i in mapped if mapped[i]==g)
    pom=sum(1 for i in mapped if mapped[i]==g and len(vd[i])>3 and vd[i][3])
    print(f"  гр.{g} «{names[g]}»: {n} записей, {len(vals)} разных значений, макс.доля {100*vals.most_common(1)[0][1]/n:.0f} %, пометок {pom}")
